        typeAnnotation = typeTokens.join("");
      }

      params.push({ name: paramName, typeAnnotation });
      match(T.Comma);
    }
    return params;
  }

  function parseBody(): Stmt[] {
    const stmts: Stmt[] = [];
    while (!at(T.RBrace) && !at(T.EOF)) stmts.push(parseStmt());
    return stmts;
  }

  return parseProgram();
}

